from pathlib import Path

import pytest

from great_docs._build import outputs
from great_docs._layout import Layout
from great_docs._utils import QUARTO_YML_HEADER
from tests.support import write_config


def _generated_project(path: Path) -> Path:
    """Create a Quarto project marked as generated by Great Docs"""
    path.mkdir()
    (path / "_quarto.yml").write_text(QUARTO_YML_HEADER, encoding="utf-8")
    return path


@pytest.mark.parametrize(
    ("claim", "directory"),
    [
        ("user_guide: user_guide\n", "user_guide"),
        ("user_guide:\n  - section: Intro\n    contents: [intro.qmd]\n", "user_guide"),
        ("custom_pages: custom\n", "custom"),
    ],
    ids=["user_guide-string", "user_guide-list", "custom_pages"],
)
def test_validate_rejects_directory_claimed_by_a_section(
    tmp_path: Path, claim: str, directory: str
):
    config = write_config(tmp_path, f"{claim}sections:\n  - title: Claimed\n    dir: {directory}\n")
    (tmp_path / directory).mkdir()

    with pytest.raises(ValueError, match=f"'{directory}' is claimed by both"):
        outputs.validate(config, Layout.make(tmp_path))


def test_validate_rejects_a_foreign_build_directory(tmp_path: Path):
    config = write_config(tmp_path)
    (tmp_path / "great-docs").mkdir()
    (tmp_path / "great-docs" / "notes.md").write_text("mine\n")

    with pytest.raises(ValueError, match="not a Great Docs-generated"):
        outputs.validate(config, Layout.make(tmp_path))


def test_remove_deletes_configuration_and_generated_directories(tmp_path: Path):
    write_config(tmp_path, "parser: numpy\n")
    build_dir = _generated_project(tmp_path / "great-docs")
    historical = _generated_project(tmp_path / "great-docs-0.2")
    lines: list[str] = []

    outputs.remove(Layout.make(tmp_path), report=lines.append)

    assert not (tmp_path / "great-docs.yml").exists()
    assert not build_dir.exists()
    assert not historical.exists()
    assert lines == [
        "Removed great-docs.yml",
        "Removed great-docs/ directory",
        "Removed great-docs-0.2/ directory",
    ]


def test_remove_keeps_unrecognised_and_linked_directories(tmp_path: Path):
    write_config(tmp_path, "parser: numpy\n")
    notes = tmp_path / "great-docs-notes"
    notes.mkdir()
    (notes / "_quarto.yml").write_text("project:\n  type: website\n# Generated by Great Docs\n")
    target = _generated_project(tmp_path / "historical-target")
    link = tmp_path / "great-docs-linked"
    link.symlink_to(target, target_is_directory=True)

    outputs.remove(Layout.make(tmp_path), report=print)

    assert notes.is_dir()
    assert link.is_symlink()
    assert target.is_dir()


def test_remove_without_output_reports_nothing(tmp_path: Path):
    lines: list[str] = []

    outputs.remove(Layout.make(tmp_path), report=lines.append)

    assert lines == []
